        {deck.map((face, index) => (
          <Card
            key={index}
            index={index}
            size={size}
            face={faceUp.has(index) ? face : null}
            matched={matchedCards.has(index)}
            tabIndex={focused === index ? 0 : -1}
            activate={activateCard}
            focus={cardFocused}
            keyDown={cardKeyDown}
            clicked={cardClicked}
          />
        ))}
      </div>
    </div>
  );
}
